#define _GNU_SOURCE
#include <time.h>
#include <stdio.h>
#include <unistd.h>
#include <sched.h>
#include <stdlib.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <string.h>
static long long wall,cpu; static int core,freq,enabled; static char exe[4096];
static long long ns(clockid_t c){struct timespec t;clock_gettime(c,&t);return t.tv_sec*1000000000LL+t.tv_nsec;}
static int frequency(int c){char p[160];snprintf(p,sizeof p,"/sys/devices/system/cpu/cpu%d/cpufreq/scaling_cur_freq",c);FILE*f=fopen(p,"r");int n=0;if(f){fscanf(f,"%d",&n);fclose(f);}return n;}
__attribute__((constructor))static void start(){int n=readlink("/proc/self/exe",exe,sizeof exe-1);if(n<0)return;exe[n]=0;if(!strstr(exe,".program"))return;enabled=1;core=sched_getcpu();freq=frequency(core);wall=ns(CLOCK_MONOTONIC);cpu=ns(CLOCK_PROCESS_CPUTIME_ID);}
__attribute__((destructor))static void end(){if(!enabled)return;long long c=ns(CLOCK_PROCESS_CPUTIME_ID)-cpu,w=ns(CLOCK_MONOTONIC)-wall;struct rusage r;getrusage(RUSAGE_SELF,&r);int e=sched_getcpu();char line[4600];int n=snprintf(line,sizeof line,"{\"pid\":%d,\"exe\":\"%s\",\"wall_ns\":%lld,\"cpu_ns\":%lld,\"cpu_start\":%d,\"cpu_end\":%d,\"khz_start\":%d,\"khz_end\":%d,\"minor_faults\":%ld,\"major_faults\":%ld,\"voluntary_cs\":%ld,\"involuntary_cs\":%ld}\n",getpid(),exe,w,c,core,e,freq,frequency(e),r.ru_minflt,r.ru_majflt,r.ru_nvcsw,r.ru_nivcsw);int fd=open(getenv("JAYDB_WORKER_CLOCK"),O_WRONLY|O_CREAT|O_APPEND,0600);if(fd>=0){write(fd,line,n);close(fd);}}
